:BuyerRoleAssignment a owl:Class ;
    rdfs:label "Buyer Role Assignment" ;
    rdfs:comment "A role assignment where the agent role is Buyer." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( :RoleAssignment [ a owl:Restriction ; owl:onProperty :hasAgentRole ; owl:hasValue :Buyer ] ) ] .

:DetailSection rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasLine ; owl:allValuesFrom :InvoiceLine ] .
:InvoiceMessage rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasOrganizationRole ; owl:someValuesFrom :RoleAssignment ] .

# General Class Axiom for ValidInvoice (CQ13)
:ValidInvoice owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
        :InvoiceMessage
        [ a owl:Restriction ; owl:onProperty :hasInvoiceNumber ; owl:someValuesFrom xsd:string ]
        [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :HeaderSection ]
        [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :DetailSection ]
        [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :SummarySection ]
        [ a owl:Restriction ; owl:onProperty :hasOrganizationRole ; owl:someValuesFrom :RoleAssignment ]
        [ a owl:Restriction ; owl:onProperty :hasAmount ; owl:someValuesFrom :Amount ]
        [ a owl:Restriction ; owl:onProperty :hasTax ; owl:someValuesFrom :Tax ]
        [ a owl:Restriction ; owl:onProperty :alignsWithEN16931 ; owl:someValuesFrom :EN16931Alignment ]
        [ a owl:Restriction ; owl:onProperty :alignsWithP2PO ; owl:someValuesFrom :P2POAlignment ]
        [ a owl:Restriction ; owl:onProperty :validatedBySHACL ; owl:someValuesFrom :SHACLConstraint ]
    )
] .

